import java.util.*;
class Main{
    public static void main(String[] args){
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] nums = new int[n+1];
        for(int i=0;i<n;i++) nums[i+1] = in.nextInt();
        boolean[] visited = new boolean[n+1];
        long ans=0;
        for(int i=1;i<n+1;i++){
            long size = 0;
            int j = nums[i];
            while(!visited[j]){
                visited[j]=true;
                size++;
                j = nums[j];
            }
            ans += size*size;
        }
        System.out.println(ans);
    }
}
