#include <bits/stdc++.h>

using namespace std;
typedef long long ll;
const int maxn = 1e5 +10;

int dp[maxn];
int nx[maxn];
int vis[maxn];
int sz[maxn];
int num;
void dfs(int now)
{
	if(vis[now]) return ;
	vis[now] = 1;
	num++;
	dfs(nx[now]);
}
int main()
{
	int n;
	cin>>n;
	for(int i=1;i<=n;i++)
	{
		int a;
		scanf("%d",&a);
		nx[i] = a;
		dp[a]++;
		sz[i] = 1;
	}
	queue<int>v;
	for(int i=1;i<=n;i++)
	{
		if(dp[i]==0)
		{
			v.push(i);
		}
	}
	long long ans = n;
	while(!v.empty())
	{
		int now = v.front();
		v.pop();
		ans += sz[now];
		vis[now] = 1;
		int nex = nx[now];
		sz[nex] += sz[now];
		dp[nex]--;
		if(dp[nex]==0)
			v.push(nex);
	}
	for(int i=1;i<=n;i++)
	{
		if(!vis[i])
		{
			num = 0;
			dfs(i);
			ans += 1ll*num*(num-1);
		}
	}
	cout<<ans<<endl;
	return 0;
}
